{
  "name": "express-validation-app",
  "version": "1.0.0",
  "description": "Express application with input validation",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest"
  },
  "keywords": ["express", "validation", "api"],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "nodemon": "^3.0.1",
    "jest": "^29.6.2"
  },
  "engines": {
    "node": ">=16.0.0"
  }
}

events {
    worker_connections 1024;
}

http {
    upstream app_servers {
        server app:3000;
    }

    server {
        listen 80;
        server_name _;

        # Security headers
        add_header X-Frame-Options "SAMEORIGIN" always;
        add_header X-Content-Type-Options "nosniff" always;
        add_header Referrer-Policy "strict-origin-when-cross-origin" always;

        # Rate limiting
        limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;

        location / {
            proxy_pass http://app_servers;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection 'upgrade';
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_cache_bypass $http_upgrade;

            # Apply rate limiting
            limit_req zone=api burst=20 nodelay;
        }

        # Health check endpoint
        location /health {
            proxy_pass http://app_servers/health;
            access_log off;
        }
    }
}

const request = require('supertest');
const app = require('./app');

describe('POST /users validation tests', () => {
  it('should reject request with missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ email: 'test@example.com' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Missing name field in request body');
  });

  it('should reject request with null name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: null });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Missing name field in request body');
  });

  it('should reject request with non-string name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Name field must be a string');
  });

  it('should reject request with empty string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Name field cannot be empty');
  });

  it('should reject request with whitespace-only name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '   ' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Name field cannot be empty');
  });

  it('should accept request with valid string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'John Doe' });

    expect(response.status).toBe(201);
    expect(response.body.message).toBe('User created successfully');
    expect(response.body.user.name).toBe('John Doe');
    expect(response.body.user.email).toContain('@example.com');
  });
});

// Example API requests to test the validation
