console.log("1. Valid Request:");
console.log("POST /users");
console.log("Content-Type: application/json");
console.log('Body: {"name": "John Doe"}');
console.log("Expected Response: 201 Created\n");

console.log("2. Missing Name Field:");
console.log("POST /users");
console.log("Content-Type: application/json");
console.log('Body: {"email": "test@example.com"}');
console.log("Expected Response: 400 Bad Request");
console.log('Error: {"error": "Missing name field in request body"}\n');

console.log("3. Non-String Name:");
console.log("POST /users");
console.log("Content-Type: application/json");
console.log('Body: {"name": 123}');
console.log("Expected Response: 400 Bad Request");
console.log('Error: {"error": "Name field must be a string"}\n');

console.log("4. Empty String Name:");
console.log("POST /users");
console.log("Content-Type: application/json");
console.log('Body: {"name": ""}');
console.log("Expected Response: 400 Bad Request");
console.log('Error: {"error": "Name field cannot be empty"}\n');

console.log("5. Whitespace-Only Name:");
console.log("POST /users");
console.log("Content-Type: application/json");
console.log('Body: {"name": "   "}');
console.log("Expected Response: 400 Bad Request");
console.log('Error: {"error": "Name field cannot be empty"}\n');

console.log("=== Testing with curl ===");
console.log('Valid: curl -X POST http://localhost:3000/users -H "Content-Type: application/json" -d \'{"name":"Alice"}\'');
console.log('Missing: curl -X POST http://localhost:3000/users -H "Content-Type: application/json" -d \'{"email":"test@test.com"}\'');
