// Test script to verify the POST endpoint validation
const http = require('http');

const baseUrl = 'http://localhost:3000';

const testCases = [
  {
    name: 'Valid request',
    data: { name: 'John Doe' },
    expectedStatus: 201
  },
  {
    name: 'Missing name field',
    data: { email: 'test@example.com' },
    expectedStatus: 400
  },
  {
    name: 'Null name',
    data: { name: null },
    expectedStatus: 400
  },
  {
    name: 'Non-string name (number)',
    data: { name: 123 },
    expectedStatus: 400
  },
  {
    name: 'Empty string name',
    data: { name: '' },
    expectedStatus: 400
  },
  {
    name: 'Whitespace-only name',
    data: { name: '   ' },
    expectedStatus: 400
  }
];

function runTest(testCase) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(testCase.data);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/users',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const passed = res.statusCode === testCase.expectedStatus;
        console.log(`${testCase.name}:`);
        console.log(`  Status: ${res.statusCode} (expected: ${testCase.expectedStatus})`);
        console.log(`  Result: ${passed ? '✓ PASS' : '✗ FAIL'}`);
        if (data) {
          console.log(`  Response: ${data}`);
        }
        console.log('');
        resolve(passed);
      });
    });

    req.on('error', (err) => {
      console.error(`Error in test "${testCase.name}": ${err.message}`);
      reject(err);
    });

    req.write(postData);
    req.end();
  });
}

async function runAllTests() {
  console.log('Starting validation tests...\n');

  // Start the server
  const { spawn } = require('child_process');
  const server = spawn('node', ['app.js']);

  // Wait for server to start
  await new Promise(resolve => setTimeout(resolve, 2000));

  let passedTests = 0;
  let failedTests = 0;

  for (const testCase of testCases) {
    try {
      const passed = await runTest(testCase);
      if (passed) {
        passedTests++;
      } else {
        failedTests++;
      }
    } catch (err) {
      console.error(`Test "${testCase.name}" failed with error:`, err.message);
      failedTests++;
    }
    // Small delay between tests
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  // Kill the server
  server.kill();

  console.log('\n=== Test Summary ===');
  console.log(`Total tests: ${testCases.length}`);
  console.log(`Passed: ${passedTests}`);
  console.log(`Failed: ${failedTests}`);

  if (failedTests > 0) {
    process.exit(1);
  }
}

// Export for manual testing
if (require.main === module) {
  runAllTests().catch(console.error);
}

module.exports = { runAllTests, testCases };

