const request = require('supertest');
const app = require('./app');

describe('POST /users validation', () => {
  it('should return 201 for valid request', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'John Doe' })
      .expect(201);

    expect(response.body.message).toBe('User created successfully');
    expect(response.body.user.name).toBe('John Doe');
  });

  it('should return 400 for missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({})
      .expect(400);

    expect(response.body.error).toBe('Missing required field: name');
  });

  it('should return 400 for non-string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 })
      .expect(400);

    expect(response.body.error).toBe('Invalid data type: name must be a string');
  });

  it('should return 400 for empty string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' })
      .expect(400);

    expect(response.body.error).toBe('Invalid value: name cannot be empty');
  });

  it('should return 400 for whitespace-only name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '   ' })
      .expect(400);

    expect(response.body.error).toBe('Invalid value: name cannot be empty');
  });
});

