async function runTests() {
  console.log('Testing POST /users endpoint validation...\n');

  // Test 1: Valid request
  console.log('Test 1: Valid request with name "Charlie"');
  const validResponse = await request(app)
    .post('/users')
    .send({ name: 'Charlie' })
    .set('Accept', 'application/json');
  console.log(`Status: ${validResponse.status}, Message: ${validResponse.body.message}`);

  // Test 2: Missing name field
  console.log('\nTest 2: Missing name field');
  const missingResponse = await request(app)
    .post('/users')
    .send({})
    .set('Accept', 'application/json');
  console.log(`Status: ${missingResponse.status}, Error: ${missingResponse.body.error}`);

  // Test 3: Non-string name
  console.log('\nTest 3: Non-string name (number)');
  const numberResponse = await request(app)
    .post('/users')
    .send({ name: 123 })
    .set('Accept', 'application/json');
  console.log(`Status: ${numberResponse.status}, Error: ${numberResponse.body.error}`);

  // Test 4: Empty string name
  console.log('\nTest 4: Empty string name');
  const emptyResponse = await request(app)
    .post('/users')
    .send({ name: '' })
    .set('Accept', 'application/json');
  console.log(`Status: ${emptyResponse.status}, Error: ${emptyResponse.body.error}`);

  // Test 5: Whitespace-only name
  console.log('\nTest 5: Whitespace-only name');
  const whitespaceResponse = await request(app)
    .post('/users')
    .send({ name: '   ' })
    .set('Accept', 'application/json');
  console.log(`Status: ${whitespaceResponse.status}, Error: ${whitespaceResponse.body.error}`);

  console.log('\nAll tests completed!');
}

// Export for testing
module.exports = { runTests };

// Run tests if called directly
